UPDATE companies SET description='Arcamed is based in Indianapolis, Indiana. The company was founded in 2012 by Greg Maurer and Kevin Etzkorn after they recognized that orthopedic original equipment manufacturers were consistently underserved by their supply chain, facing long lead times, poor quality control, and weak customer service.

Arcamed manufactures surgical case and tray systems, precision caddies for implants, and rigid sterilization containers. The facility operates under 5S and Lean Manufacturing principles and is equipped with an automated optical assembly inspection system, a coordinate measuring machine (CMM), a Micro‑Vu vision system, and an optical comparator. The company reports quality metrics including 99.1 % on‑time delivery, 96.9 % on‑time‑in‑full, and 98.4 % orders defect‑free.

The customer base spans enterprise, mid‑market, and startup orthopedic OEMs. Arcamed positions itself as an extension of its partners’ teams, providing design transfer support, validated processes, and documentation that meets regulatory requirements.

The founders started Arcamed to deliver concierge‑level service, industry‑lead times, and on‑time delivery — commitments the company says differentiate it from transactional suppliers. Its quality management system is certified to ISO 13485:2016 and the facility is FDA registered.', certifications=ARRAY['ISO 13485:2016','FDA Registered']::text[], profile='{"capabilities": ["Surgical case and tray systems", "Precision caddies for implants", "Rigid sterilization containers", "Automated optical assembly inspection", "Coordinate measuring machine (CMM) inspection", "Micro\u2011Vu vision system inspection", "Optical comparator inspection", "Quality management system (ISO 13485:2016)", "FDA regulatory compliance", "Design transfer support", "Lean manufacturing (5S)"], "industries": ["Orthopedic original equipment manufacturers (OEMs)", "Medical device manufacturers", "Enterprise OEMs", "Mid\u2011market OEMs", "Startup OEMs"], "materials": [], "equipment": ["Automated Optical Assembly Inspection System", "Coordinate Measuring Machine (CMM)", "Vision System (Micro\u2011Vu)", "Optical Comparator"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Concierge\u2011level service and relational partnership model", "Industry\u2011leading lead times and on\u2011time delivery performance", "Validated manufacturing processes with automated optical inspection", "5S and Lean Manufacturing discipline throughout the facility", "ISO\u202f13485:2016 certification and FDA registration"], "facts_used": ["Founded 2012 by Greg Maurer and Kevin Etzkorn -> /about", "Headquarters Indianapolis, Indiana -> db", "ISO 13485:2016 certified -> /", "FDA registered -> /", "Manufactures surgical case & tray systems, caddies, rigid sterilization containers -> /", "Serves orthopedic OEMs (enterprise, mid-market, startup) -> /about", "Quality equipment includes Automated Optical Assembly Inspection System, CMM, Vision System (Micro-Vu), Optical Comparator -> /quality", "Quality metrics: 99.1% on-time delivery, 96.9% on-time-in-full, 98.4% orders defect-free -> /", "5S and Lean Manufacturing principles -> /", "Concierge service, industry-leading lead times, on-time delivery as differentiators -> /about", "Design transfer support -> /", "Validated processes, documentation compliance -> /quality"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Your Elite Provider of Surgical Case & Tray Systems", "founded_year": "2012", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='arcamed' AND approved AND profile IS NULL;
UPDATE companies SET description='Arch Plastics Packaging operates from Chattanooga, Tennessee, where it has been producing plastic containers since 1951.

The firm manufactures custom-molded plastic containers, primarily using high-density polyethylene (HDPE). Depending on volume and bottle specifications, it employs either injection blow molding (IBM) or extrusion blow molding (EBM). Quality services include first-in-first-out (FIFO) inventory control for all raw materials and finished goods, and a certificate of compliance with raw-material documentation accompanies every shipment. The company also develops custom packaging designs and colors to differentiate clients’ products.

Arch Plastics serves the pharmaceutical and personal care industries, providing containers that meet stringent regulatory requirements. Its customer base includes brands seeking compliant, pharmaceutical-grade packaging.

The company emphasizes versatility and quick response as keys to its success, underpinned by strict adherence to current Good Manufacturing Practices (cGMP) and Total Quality Management (TQM) systems. Its stated mission is to deliver high-quality pharmaceutical-grade containers while minimizing environmental impact and promoting social governance.', certifications=ARRAY['FDA APPROVED','ANSI','MIL STD','CGMP']::text[], profile='{"capabilities": ["Custom plastic container molding", "Injection blow molding (IBM)", "Extrusion blow molding (EBM)", "FIFO inventory management", "Certificate of Compliance documentation", "Custom packaging design", "cGMP compliant manufacturing", "Total Quality Management (TQM) systems"], "industries": ["Pharmaceutical", "Personal Care"], "materials": ["HDPE (High-Density Polyethylene)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Versatile, quick-response manufacturing approach", "Strict cGMP and Total Quality Management compliance", "Custom packaging design and color options", "FIFO inventory control for all materials", "Certificate of Compliance included with every shipment"], "facts_used": ["Founded in 1951 -> db", "Headquartered in Chattanooga, Tennessee -> db and page /", "Produces plastic containers for Pharmaceutical and Personal Care Industries -> page /", "Follows cGMP and TQM systems -> page /", "Certifications: FDA APPROVED, ANSI, MIL STD, CGMP -> db", "Uses FIFO procedures for raw materials and finished products -> db (products)", "Provides Certificate of Compliance with each shipment -> db (products)", "Offers custom packaging design and colors -> db (products)", "Uses IBM or EBM processes for HDPE products -> db (products)", "Mission: produce high-quality pharmaceutical grade plastic containers implementing GMPs and TQM -> page /", "Vision: reliable and quality supplier globally -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Arch Plastics Packaging (ARCH) is a reliable producer and supplier of quality plastic containers for the Pharmaceutical and Personal Care Industries.", "founded_year": "1951", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='arch-plastics' AND approved AND profile IS NULL;
UPDATE companies SET description='Archbold Furniture has operated in Archbold, Ohio since 1900. The company is led by owner and president Pat McNamara and now encompasses three brands: Archbold Furniture, Amish Essentials, and Bob Timberlake® American Home.

The company manufactures solid wood furniture for every room — bedroom, dining, living room, home office, bookcases, and kitchen storage. Production uses select solid hardwoods such as alder and maple, with English dovetail drawer construction and smooth glides. Finishes are applied by Amish craftsmen using catalyzed conversion varnish for moisture, heat, and scratch resistance.

Archbold Furniture serves the residential furniture market, supplying dealers who sell to end consumers. Its three brands address different price points and styles: the core Archbold line features solid alder with custom Amish finishes; Amish Essentials offers 100% Amish-handcrafted pieces from locally sourced hardwoods; and Bob Timberlake® American Home presents artist-designed collections built by American craftsmen.

Pat McNamara emphasizes continual improvement to ensure a satisfied customer for life. Differentiators include American-made construction since 1900, solid tops and sides, and a finish system designed for durability.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Solid wood furniture manufacturing", "English dovetail joinery", "Catalyzed conversion varnish finishing", "Custom Amish finishing", "Furniture design and development", "Dealer program management", "Amish handcrafted furniture production"], "industries": ["Residential furniture", "Home furnishings"], "materials": ["Alder", "Maple", "Solid hardwoods", "Premier hardwoods"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Solid tops, sides, and drawer parts on all case goods", "English dovetail drawers with smooth glides", "Custom Amish finishes applied by Amish craftsmen", "Catalyzed conversion varnish resistant to moisture, heat, and scratches", "Three distinct brands under one company: Archbold Furniture, Amish Essentials, Bob Timberlake\u00ae American Home"], "facts_used": ["Founded in 1900 in Archbold, Ohio -> db", "Owner/President Pat McNamara -> /", "Three brands: Archbold Furniture, Amish Essentials, Bob Timberlake\u00ae American Home -> /", "Manufactures solid wood furniture for bedroom, dining, living room, home office, bookcases, kitchen storage -> /", "Uses select solid hardwoods including alder and maple -> /", "English dovetail drawer construction and smooth glides -> /", "Custom Amish finishes applied by Amish craftsmen using catalyzed conversion varnish -> /", "High Point showroom -> /", "Sells through dealer network -> /", "Core values guided by Christian principles -> /", "Commitment to quality, service, value, continual improvement -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Solid alder furniture built in Archbold, Ohio since 1900, featuring custom Amish finishes.", "founded_year": "1900", "employee_count":