UPDATE companies SET description='Arctic Restaurant Service & Supply has operated from Madisonville, Kentucky since 1973. The company was founded as a family-owned business and remains under family ownership today, serving the western Kentucky region and surrounding areas.

The company supplies commercial cooking equipment, refrigeration systems, and a full range of restaurant supplies including cookware and tableware. It carries major brands such as Vulcan, Duke, Blodgett, Henny Penny, True Manufacturing, Victory Refrigeration, and Delfield. Beyond sales, Arctic provides installation, planned maintenance, 24/7 emergency repair, and a parts department that stocks inventory and can special-order items typically within three to four business days. The business also rents refrigerated trailers for events and seasonal needs, and offers commercial HVAC services.

Arctic serves a broad spectrum of foodservice operations, from small cafes and catering outfits to large commercial kitchens in hotels, schools, and healthcare facilities. Its customer base includes restaurants, hotels, educational institutions, and medical centers across western Kentucky.

The company emphasizes its status as an authorized warranty provider for major brands, with factory-trained, licensed, and insured technicians. It differentiates itself through 24/7 emergency response, free delivery within a 60-mile radius for trailer rentals, and a local, family-owned presence spanning more than five decades.', certifications=ARRAY['Authorized warranty provider for major brands']::text[], profile='{"capabilities": ["Commercial cooking equipment sales", "Commercial refrigeration sales, installation, and maintenance", "Emergency repair services (24/7)", "Preventative maintenance plans", "Parts and accessories supply (stock and special order)", "Refrigerated trailer rentals", "Restaurant supply sales (cookware, tableware)", "Delivery and in-store pickup", "Commercial HVAC services", "Planned maintenance programs"], "industries": ["Restaurants", "Hotels", "Schools", "Healthcare facilities", "Cafes", "Commercial kitchens", "Catering operations", "Food trucks"], "materials": [], "equipment": ["Vulcan cooking equipment", "Duke cooking equipment", "Blodgett ovens", "Henny Penny fryers", "True Manufacturing refrigeration", "Victory Refrigeration", "Delfield refrigeration", "Manitowoc Ice machines", "Scotsman ice machines", "Middleby Marshall ovens"], "volume": "", "lead_time": "3-4 business days for special order parts", "tolerances": "", "built_on": ["Authorized warranty provider for major brands", "Factory-trained, licensed, and insured service technicians", "24/7 emergency repair service", "Free delivery within 60 miles on refrigerated trailer rentals", "Family-owned and locally operated since 1973"], "facts_used": ["Founded 1973 -> db", "Headquarters Madisonville, KY -> db", "Family-owned -> / (homepage)", "Authorized warranty providers -> / (homepage)", "Factory-trained technicians -> / (homepage)", "Licensed and insured -> / (homepage)", "24/7 emergency service -> / (homepage)", "Free delivery within 60 miles for refrigerated trailers -> / (homepage)", "Special orders arrive within 3-4 business days -> / (homepage)", "Industries served: restaurants, hotels, schools, healthcare facilities -> / (homepage)", "Brands carried: Vulcan, Duke, Blodgett, Henny Penny, True Manufacturing, Victory Refrigeration, Delfield, etc. -> / (homepage)", "Associations: CFESA Trade Association, ISC Buying Group -> /about", "License HM06616 -> /about", "Languages: English -> /about", "Commercial HVAC services -> /about", "Planned maintenance programs -> /about", "Refrigerated trailer rentals -> / (homepage)", "Parts & accessories stock and special order -> / (homepage)", "Delivery and in-store pickup -> /about"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We carry a wide range of brands including Vulcan, Duke, Blodgett, and Henny Penny. From ovens and fryers to grills and ranges, we''ve got the tools you need to create culinary masterpieces.", "founded_year": "1973", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": ["English"], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='arctic-restaurant-service-supply' AND approved AND profile IS NULL;
UPDATE companies SET description='Arizona Automotive Equipment, also known as Mohawk Automotive Lifts Southwest, has operated from Phoenix, Arizona since 2004. The company was founded by Mike and Karen Green to provide annual lift safety inspections and detailed reports for OSHA compliance. In January 2021, ownership passed to Jason and Brandi Byers, a husband-and-wife team who continue the family-run legacy.

The business supplies heavy-duty automotive lifts and equipment for commercial shops and personal garages, carrying brands such as Mohawk Lifts, Hunter Engineering, Challenger Lifts, Tuxedo Lifts, and Samson. Its product range includes two-post, four-post, mobile column, scissor, and specialty lifts for vehicles from passenger cars to heavy-duty trucks. In addition to sales, the company provides ALI-certified lift inspections and in-house installation services performed by its own technicians.

The company''s inspectors are qualified to examine any lift regardless of manufacturer, brand, or age, issuing serialized ALI inspection labels that serve as proof of compliance for code enforcement.

The Byerses emphasize a personal-touch approach, offering personalized service, a comprehensive catalog, and a 100% satisfaction guarantee. Their ALI-certified inspectors and focus on OSHA compliance differentiate the business in a market where safety certification is often a minimum requirement.', certifications=ARRAY['ALI Certified Lift Inspector','OSHA compliance']::text[], profile='{"capabilities": ["Automotive lift sales (two-post, four-post, mobile column, scissor, specialty)", "ALI-certified lift inspections", "Lift installation", "OSHA compliance reporting", "Equipment consultation and selection"], "industries": ["Automotive repair shops", "Commercial garages", "Personal garages", "Fleet maintenance", "Heavy-duty truck service"], "materials": [], "equipment": ["Mohawk Lifts", "Hunter Engineering", "Challenger Lifts", "Tuxedo Lifts", "Samson"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ALI-certified lift inspectors on staff", "In-house installation for single lifts to multi-lift projects", "100% satisfaction guarantee on every purchase", "Family-owned operation with personalized service", "Authorized dealer for Mohawk, Hunter, Challenger, Tuxedo, and Samson lifts"], "facts_used": ["Founded 2004 by Mike and Karen Green -> /about", "Owned by Jason and Brandi Byers since January 2021 -> /about", "Family-run operation -> /", "Sells heavy-duty automotive lifts and equipment -> /", "Provides ALI-certified lift inspections -> /", "Carries brands Mohawk, Hunter, Challenger, Tuxedo, Samson -> /", "Offers two-post, four-post, mobile column, scissor, specialty lifts -> /", "In-house installation services -> /", "Serves commercial shops and personal garages in Southwest -> /", "ALI Certified Lift Inspectors -> /", "OSHA compliance support -> /", "100% satisfaction guarantee -> /", "Personalized service -> /", "Headquarters Phoenix, AZ -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Arizona Automotive Equipment, LLC sells heavy-duty automotive lifts and equipment for commercial shops and personal garages, and provides ALI-certified lift inspections.", "founded_year": "2004", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='arizona-automotive-equipment' AND approved AND profile IS NULL;
UPDATE companies SET description='Arizona Fabrication Solutions is based in Queen Creek, Arizona, and was founded in 2013.

The shop specializes in custom architectural and structural steel fabrication for residential and commercial construction projects across Arizona. Core services include stair railing replacement and installation, gate fabrication (including entry gates, rolling gates, and block wall removal for larger openings), and custom metal ornamentals such as indoor furniture and outdoor trellises. The team works with architectural and structural steel to deliver tailored metalwork for builders and homeowners.

Primary customers are in the residential and commercial construction sectors, including contractors, architects, and property owners throughout Arizona. Projects range from single-family home railing upgrades to commercial gate installations and decorative metal accents for both interior and exterior applications.

The company emphasizes its veteran-owned, family-operated structure as a differentiator, highlighting a commitment to custom projects and direct client collaboration.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom architectural steel fabrication", "Custom structural steel fabrication", "Stair railing fabrication and installation", "Gate fabrication (entry, rolling, custom)", "Custom metal ornamental fabrication", "Indoor furniture fabrication", "Outdoor trellis fabrication"], "industries": ["Residential construction", "Commercial construction", "Architectural steel", "Structural steel"], "materials": ["Architectural steel", "Structural steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Specializes in custom architectural and structural steel fabrication", "Serves residential and commercial construction across Arizona", "Offers custom metal ornamentals including indoor furniture and outdoor trellises"], "facts_used": ["Located in Queen Creek, Arizona -> db", "Founded in 2013 -> db", "Veteran family owned and operated -> db (description)", "Founders: Shannon Miazga (Army veteran) and Bobby Padilla -> /about", "Specializes in custom architectural and structural steel for residential and commercial construction -> / (home)", "Services: stair railings, gates, custom metal ornamentals (indoor furniture, outdoor trellis) -> / (home)", "Serves residential and commercial construction throughout Arizona -> / (home)"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We are a metal fabrication contractor specializing in custom architectural and structural steel for residential and commercial construction throughout the state of Arizona.", "founded_year": "2013", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Veteran-owned", "Family-owned"]}'::jsonb, updated_at=now() WHERE slug='arizona-fabrication-solutions' AND approved AND profile IS NULL;
UPDATE companies SET description='Arizona Mobile Meat Processing operates from Williams, Arizona, where founder Jake Giles launched the business in 2009 after two decades of cutting meat. Giles serves as owner and operator of the mobile processing service, which travels to ranches and homes across northern Arizona to handle domestic livestock.

The company runs a state‑inspected facility approved for resale and carries commercial inspection from the Arizona Department of Agriculture (AZDA). Its mobile unit provides on‑site slaughter, cutting, and wrapping for beef, lamb, goats, and swine, while a separate wild‑game division processes antelope, deer, elk, and javelina during hunting seasons.

Customers include ranchers, hunting families, and local 4‑H clubs that the company sponsors. The service covers domestic livestock for private owners and auction participants (Coconino, Maricopa, Verde Valley, Yavapai county auctions) as well as hunters seeking custom processing of harvested game.', certifications=ARRAY['AZDA inspected','State inspected for resale']::text[], profile='{"capabilities": ["Mobile meat processing", "Domestic livestock processing (beef, lamb, goat, swine)", "Wild game processing (antelope, deer, elk, javelina)", "State\u2011inspected processing for resale", "AZDA\u2011compliant commercial inspection", "Custom cutting and wrapping", "On\u2011site slaughter and processing", "Auction animal processing"], "industries": ["Meat processing", "Livestock processing", "Game meat processing", "Agriculture", "Hunting and outdoor recreation"], "materials": ["Beef", "Lamb", "Goat", "Pork", "Venison", "Antelope", "Elk", "Javelina"], "equipment": ["Mobile processing unit"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["State\u2011inspected facility approved for resale", "Commercially inspected by the Arizona Department of Agriculture (AZDA)", "Mobile processing unit travels to ranches and homes", "Processes both domestic livestock and wild game", "Sponsors local 4\u2011H clubs and hunting/ranching families"], "facts_used": ["Founded 2009 by Jake Giles in Williams, AZ -> /", "Owner/Operator Jake Giles with 20 years meat cutting experience -> /", "Mobile processing unit travels to ranches/homes for domestic animals -> /", "State inspected facility for resale, commercially inspected by AZDA -> /", "Specializes in domestic livestock (beef, lamb/goats, swine) and wild game (antelope, deer, elk, javelina) -> /", "Sponsors local 4H clubs and hunting/ranching families -> /", "Headquarters at 355 Ellen Way, Williams, AZ 86046 -> /", "Operates Jake''s Butcher Shop as separate retail entity -> /"], "company_type": "Manufacturer", "makes_products": 