UPDATE companies SET description='Established in 2006 in Las Vegas, Nevada, Automotive Equipment of Nevada (AEN) draws on over 34 years of combined experience in the automotive equipment sector. The company operates as a full-service distributor, selling and servicing brands of automotive shop equipment.

AEN provides a complete range of services including equipment sales, shop design, installation, and repair. Its sales portfolio spans individual items such as jacks and oil reels up to complete alignment systems and frame-pulling bays. The design team specializes in ground-up dealership construction and major remodels, coordinating with general contractors to specify equipment early and avoid change orders. Installation crews handle projects from single lifts to facilities with more than 80 in-ground lifts, while the service department, backed by over 20 years of repair experience, addresses issues ranging from stuck lifts to leaking hydraulic lines.

AEN differentiates itself by integrating sales, design, installation, and service under one roof, ensuring that all equipment works together harmoniously. The firm holds Nevada contractor licenses 86133 and 86134, underscoring its compliance with state regulations for construction and installation work.', certifications=ARRAY['Nevada Contractor License 86133','Nevada Contractor License 86134']::text[], profile='{"capabilities": ["Equipment sales", "Shop design and layout", "Equipment installation", "Equipment repair and maintenance", "Project coordination with general contractors"], "industries": ["Automotive dealerships", "Automotive repair shops", "Collision centers", "Automotive service equipment distribution"], "materials": [], "equipment": ["Alignment systems", "Frame pulling bays", "In-ground lifts", "Oil reels", "Jacks"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Integrated sales, design, installation, and service for automotive shop equipment", "Nevada contractor licenses 86133 and 86134", "Experience with large-scale dealership projects (80+ in-ground lifts)", "Over 20 years of equipment repair expertise", "Coordination with general contractors on new-build and remodel projects"], "facts_used": ["Founded in 2006 -> db", "Headquarters in Las Vegas, Nevada -> db", "Over 34 years serving automotive industry -> /", "Full-service automotive shop equipment distributor -> /", "Services: sales, design, service, install -> /services", "Design for ground-up new build dealerships and major remodels -> /services", "Over 20 years experience repairing automotive shop equipment -> /services", "Installation from simple oil reel to entire dealership with over 80 in-ground lifts -> /services", "NV Contractor License Numbers 86133 & 86134 -> /"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "We are a full-service automotive shop equipment distributor, selling and servicing the top-tier automotive shop equipment brands.", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='automotive-equipment-of-nevada' AND approved AND profile IS NULL;
UPDATE companies SET description='Automotive Supply Center (ASC) has operated in Hilo, Hawaii, since 1955 when brothers Kazuichi and Hayato Okino opened a small auto parts shop on Piopio Street with three full-time and two part-time employees. A tsunami destroyed the original location on May 1, 1960, prompting a move to the Kanoelehua Industrial Park area the following year. The business relocated again in 1996 to its current address at 411 E Kawili St., where it now runs three warehouses.

The company stocks and sells new and rebuilt automotive parts, supplies, paint, and accessories for domestic and imported cars, trucks, and high-performance vehicles. Its inventory spans auto motor parts, electrical components, air conditioning parts, batteries, detailing products, auto body supplies, fluids, and tools. Today, Peter Okino and his son Darin Okino manage a staff of over 35 employees, many recruited from Hawaii Community College’s auto body and repair programs, with some technicians boasting over 30 years of experience.

The shop carries parts for major brands such as Honda, Ford, and Toyota, and supports both foreign and domestic models.

The Okino family attributes the company’s longevity to its knowledgeable staff and deep local ties, which enable a wide inventory selection and competitive pricing. The business was founded to meet the community’s need for reliable automotive parts and has adapted through natural disasters and growth while remaining locally based.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Automotive parts retail", "Rebuilt parts supply", "Parts consultation and lookup", "Inventory stocking and management", "Counter sales for DIY and professional customers"], "industries": ["Automotive parts and accessories", "Automotive tools and equipment", "Truck parts and supplies", "Car detailing products", "Auto body supplies"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Three warehouses stocking new and rebuilt parts for domestic and imported vehicles", "Staff with over four decades of combined experience in automotive parts", "Parts coverage for foreign and domestic cars, trucks, and high-performance vehicles", "Local hiring from Hawaii Community College auto body and repair programs"], "facts_used": ["Founded in 1955 by Kazuichi and Hayato Okino -> /", "Tsunami destroyed original shop on May 1, 1960 -> /", "Relocated to Kanoelehua Industrial Park in 1961 -> /", "Moved to current address 411 E Kawili St. in 1996 -> /", "Current management by Peter Okino and son Darin Okino -> /", "Staff of over 35 employees -> /", "Three warehouses stocking new and rebuilt automotive parts -> /", "Serves customers throughout the entire Big Island of Hawaii -> /", "Carries parts for domestic and imported cars, trucks, high-performance vehicles -> /", "Expert staff with over four decades of individual experience -> /", "Recruits from Hawaii Community College Auto Body and Auto Repair Programs -> /", "Employees with over 30 years of experience -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "ASC is the auto par