op", "makes_products": "yes", "type_evidence": "We fabricate high-quality products to suit your needs, while also offering on-site installation and plant maintenance services", "founded_year": "1953", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='avon-lake-sheet-metal-company-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Axial Medical operates a 40,000-square-foot facility in Warminster, Pennsylvania, just outside Philadelphia. The purpose-built plant was completed in 2014 to serve the medical device industry.

The company provides medical device manufacturing from prototype through production, specializing in 5-axis CNC milling, wire EDM, gun drilling, and assembly. Its shop houses over 60 5-axis CNC machines (including MAZAK, HAAS, and CHIRON mills) and FANUC wire EDMs capable of 72-hour unmanned runs. Processes hold tolerances of ±0.0001 inch and are supported by optical/video inspection and automated SPC data collection.

Axial serves medical device OEMs, producing components such as expandable implants and cannulated products. The company offers vendor-managed inventory programs and environmentally controlled assembly areas for finished devices.

Axial differentiates itself with ISO 13485:2016 certification, FDA registration, full in-house process validations, and a focus on risk mitigation and continuous improvement. Automation and robotics are employed to increase throughput and part-per-bar yield.', certifications=ARRAY['ISO 13485:2016','FDA Registered']::text[], profile='{"capabilities": ["5-axis CNC milling (high-speed, single-operation)", "Wire EDM (FANUC, 72-hour unmanned)", "Gun drilling (in-line, for cannulated products)", "Assembly & finishing", "Optical/video inspection", "Automated SPC data collection", "Full process validation", "Risk mitigation & continuous improvement", "Vendor-managed inventory", "Expandable implant production", "Part-per-bar yield optimization", "Environmentally controlled assembly"], "industries": ["Medical Device Manufacturer"], "materials": [], "equipment": ["MAZAK milling machines", "HAAS milling machines", "CHIRON milling machines", "FANUC Wire EDM", "5-axis CNC machines"], "volume": "", "lead_time": "", "tolerances": "\u00b10.0001 in", "built_on": ["ISO 13485:2016 certified and FDA registered", "Full in-house process validations", "Automation and robotics for increased productivity", "Electronic inspection data for real-time SPC analysis", "Vendor-managed inventory programs"], "facts_used": ["Headquarters in Warminster, Pennsylvania -> db", "40,000 sq ft facility built in 2014 -> /about", "Over 60 5-axis CNC machines -> /about", "ISO 13485:2016 certified -> /about", "FDA registered -> /about", "Capabilities: 5-axis milling, wire EDM, gun drilling, assembly, inspection -> capabilities, products", "Tolerances \u00b10.0001 inch -> capabilities", "Industries served: Medical Device Manufacturer -> industries_served", "Equipment: MAZAK, HAAS, CHIRON milling machines -> /about", "Equipment: FANUC Wire EDM -> /about", "Automation & robotics -> /about", "Electronic inspection data for SPC -> /about", "Full validations for in-house capabilities -> capabilities", "Vendor managed 